{"content":"/**
 * Set algebra over half-open integer intervals `[start, end)`.
 */

/**
 * Validates an interval list and all of its bounds.
 * @param {unknown} intervals Candidate interval list.
 * @returns {void}
 */
function validateIntervalList(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('interval list must be an array');
  }

  for (const interval of intervals) {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError('interval must be a two-element array');
    }

    const [start, end] = interval;
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
      throw new TypeError('interval bounds must be safe integers');
    }
    if (start > end) {
      throw new RangeError('interval start must not exceed end');
    }
  }
}

/**
 * Normalises an already validated interval list.
 * @param {Array<Array<number>>} intervals Valid interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
function normaliseValidated(intervals) {
  const sorted = intervals
    .map(([start, end]) => [start, end])
    .sort(([leftStart], [rightStart]) =>
      leftStart > rightStart ? 1 : leftStart < rightStart ? -1 : 0,
    );
  const normalised = [];

  for (const [start, end] of sorted) {
    if (start === end) continue;

    const previous = normalised.at(-1);
    if (previous !== undefined && start <= previous[1]) {
      if (end > previous[1]) previous[1] = end;
    } else {
      normalised.push([start, end]);
    }
  }

  return normalised;
}

/**
 * Normalises a list of intervals: drops empties, sorts, and coalesces
 * overlapping or touching intervals.
 * @param {unknown} intervals Interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
export function normalize(intervals) {
  validateIntervalList(intervals);
  return normaliseValidated(intervals);
}

/**
 * Union of two interval lists.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised union.
 */
export function merge(a, b) {
  validateIntervalList(a);
  validateIntervalList(b);

  const left = normaliseValidated(a);
  const right = normaliseValidated(b);
  const result = [];
  let i = 0;
  let j = 0;

  while (i < left.length || j < right.length) {
    let current;
    if (j >= right.length || (i < left.length && left[i][0] < right[j][0])) {
      current = left[i];
      i += 1;
    } else {
      current = right[j];
      j += 1;
    }

    const previous = result.at(-1);
    if (previous !== undefined && current[0] <= previous[1]) {
      if (current[1] > previous[1]) previous[1] = current[1];
    } else {
      result.push([current[0], current[1]]);
    }
  }

  return result;
}

/**
 * Intersection of two interval lists. Touching intervals do not intersect.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised intersection.
 */
export function intersect(a, b) {
  validateIntervalList(a);
  validateIntervalList(b);

  const left = normaliseValidated(a);
  const right = normaliseValidated(b);
  const result = [];
  let i = 0;
  let j = 0;

  while (i < left.length && j < right.length) {
    const start = Math.max(left[i][0], right[j][0]);
    const end = Math.min(left[i][1], right[j][1]);
    if (start < end) result.push([start, end]);

    if (left[i][1] < right[j][1]) {
      i += 1;
    } else if (right[j][1] < left[i][1]) {
      j += 1;
    } else {
      i += 1;
      j += 1;
    }
  }

  return result;
}

/**
 * Relative complement `a \ b`.
 * @param {unknown} a Interval list to subtract from.
 * @param {unknown} b Interval list to remove.
 * @returns {Array<[number, number]>} Normalised difference.
 */
export function subtract(a, b) {
  validateIntervalList(a);
  validateIntervalList(b);

  const left = normaliseValidated(a);
  const right = normaliseValidated(b);
  const result = [];
  let j = 0;

  for (const [aStart, aEnd] of left) {
    while (j < right.length && right[j][1] <= aStart) j += 1;

    let cursor = aStart;
    while (j < right.length && right[j][0] < aEnd) {
      const [bStart, bEnd] = right[j];
      if (bStart > cursor) result.push([cursor, Math.min(bStart, aEnd)]);
      cursor = Math.max(cursor, bEnd);
      if (cursor >= aEnd) break;
      j += 1;
    }
    if (cursor < aEnd) result.push([cursor, aEnd]);
  }

  return result;
}

/**
 * Total length covered by a list of intervals, counting overlaps once.
 * @param {unknown} intervals Interval list.
 * @returns {number} Number of integers covered.
 */
export function coverage(intervals) {
  validateIntervalList(intervals);
  const normalised = normaliseValidated(intervals);

  let total = 0;
  for (const [start, end] of normalised) total += end - start;
  return total;
}
